<?php require '../config/db_conn.php';require 'page-guard.php';require 'components.php';$today=date('Y-m-d');$stmt=$conn->prepare("SELECT s.*,(SELECT COUNT(*) FROM attendance a WHERE TRIM(a.STUDENT_ID)=TRIM(s.STUDENT_ID) AND DATE(a.TIME_IN)=?) attended_today FROM students s ORDER BY s.SECTION,s.STUDENT_NAME");$stmt->bind_param('s',$today);$stmt->execute();$result=$stmt->get_result();adminHead('Students');adminSidebar('students','Students','Search profiles and review today’s attendance status'); ?>
<div class="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 class="text-2xl font-black text-slate-900">Student directory</h2><p class="mt-1 text-slate-500"><?= $result->num_rows ?> registered student<?= $result->num_rows===1?'':'s' ?></p></div><div class="flex gap-3"><input id="student-search" class="w-full rounded-xl border border-slate-300 px-4 py-3 text-sm sm:w-72" placeholder="Search name or ID"><a href="add-student.php" class="shrink-0 rounded-xl bg-blue-600 px-4 py-3 text-sm font-bold text-white hover:bg-blue-700">Add student</a></div></div><div class="overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200"><div class="overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-4">Student</th><th class="px-5 py-4">ID</th><th class="px-5 py-4">Section</th><th class="px-5 py-4">Today</th><th class="px-5 py-4"></th></tr></thead><tbody id="student-rows" class="divide-y divide-slate-100"><?php while($row=$result->fetch_assoc()): ?><tr class="hover:bg-slate-50"><td class="px-5 py-4"><div class="flex items-center gap-3"><img src="../<?= htmlspecialchars($row['IMAGE_PATH']) ?>" alt="" class="h-10 w-10 rounded-full object-cover"><span class="font-bold text-slate-900"><?= htmlspecialchars($row['STUDENT_NAME']) ?></span></div></td><td class="px-5 py-4 text-slate-600"><?= htmlspecialchars($row['STUDENT_ID']) ?></td><td class="px-5 py-4"><span class="rounded-full bg-blue-50 px-3 py-1 font-bold text-blue-700"><?= htmlspecialchars($row['SECTION']??'N/A') ?></span></td><td class="px-5 py-4"><span class="rounded-full px-3 py-1 font-bold <?= $row['attended_today']?'bg-emerald-50 text-emerald-700':'bg-amber-50 text-amber-700' ?>"><?= $row['attended_today']?'Present':'Not recorded' ?></span></td><td class="px-5 py-4 text-right"><a class="font-bold text-blue-600" href="edit-student.php?id=<?= $row['ID'] ?>">Open profile</a></td></tr><?php endwhile; ?></tbody></table></div></div><script>document.getElementById('student-search').addEventListener('input',e=>document.querySelectorAll('#student-rows tr').forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase())))</script><?php adminFoot(); ?>
